def roman_to_int(s):
    romans = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    prev = 0
    for char in reversed(s):
        val = romans[char]
        if val >= prev:
            total += val
        else:
            total -= val
        prev = val
    return total
```

